async function loadWhoop(){try{const data=await jsonFetch('/app/api/whoop'),last=data.recovery.find(r=>r.score_state==='SCORED'),sleep=data.sleep.find(r=>r.score_state==='SCORED'),cycle=data.cycles.find(r=>r.score_state==='SCORED');$('whoopSignals').hidden=false;$('whoopSignals').innerHTML='<div class="label">WHOOP · naměřené signály</div><div class="detail-stats"><div><span>Recovery</span><strong>'+esc(last?.score?.recovery_score??'—')+'%</strong><small>'+esc(last?.created_at?new Date(last.created_at).toLocaleDateString('cs-CZ'):'Bez měření')+'</small></div><div><span>Sleep performance</span><strong>'+esc(sleep?.score?.sleep_performance_percentage??'—')+'%</strong></div><div><span>Strain</span><strong>'+esc(cycle?.score?.strain==null?'—':fmt(cycle.score.strain,1))+'</strong></div></div>';const existing=state.fitness?.wellness||[];const map=new Map(existing.map(r=>[r.id,r]));for(const r of data.recovery){if(r.score_state!=='SCORED')continue;const date=String(r.created_at).slice(0,10),old=map.get(date)||{id:date};map.set(date,{...old,hrv:old.hrv??r.score?.hrv_rmssd_milli,restingHR:old.restingHR??r.score?.resting_heart_rate});}state.fitness={...state.fitness,wellness:[...map.values()].sort((a,b)=>a.id.localeCompare(b.id))};renderDetails();}catch(e){$('whoopSignals').hidden=false;$('whoopSignals').textContent='WHOOP: '+e.message;}}
