function foodMessage(text){$('foodEntryStatus').textContent=text;}
function foodEditorProduct(){const p={...foodSelected,name:$('foodProductName').value.trim(),brand:$('foodBrand').value.trim()};for(const field of ['calories_100g','protein_100g','carbs_100g','fat_100g','fiber_100g','salt_100g']){const value=$('food-'+field).value.trim().replace(',','.');p[field]=value===''?null:Number(value);}return p;}
