async function searchFood(){const b=$('foodSearchButton');b.disabled=true;foodMessage('Dohledávám výrobek…');try{const name=$('foodQuery').value.trim(),barcode=$('foodBarcode').value.trim();if(!name&&!barcode)throw new Error('Napiš název nebo čárový kód.');const r=await jsonFetch('/app/api/food/search',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,barcode})});foodCandidates=r.candidates?.length?r.candidates:r.product?[r.product]:[];$('foodResults').innerHTML=foodCandidates.map((p,i)=>'<button type="button" class="food-result" data-food-index="'+i+'"><strong>'+esc(p.name)+'</strong><span class="small">'+esc(p.brand||'Bez značky')+(p.quantity?' · '+esc(p.quantity):'')+' · '+(p.calories_100g==null?'energie neuvedena':fmt(p.calories_100g)+' kcal / 100 g')+'</span></button>').join('');$('foodResults').querySelectorAll('[data-food-index]').forEach(b=>b.onclick=()=>selectFoodProduct(foodCandidates[Number(b.dataset.foodIndex)]));if(foodCandidates.length===1)selectFoodProduct(foodCandidates[0]);foodMessage(foodCandidates.length?'Vyber správný výrobek a množství.':'Výrobek nebyl nalezen. Zkus přesnou značku nebo načti etiketu.');}catch(e){foodMessage(e.message);}finally{b.disabled=false;}}
async function readFoodPhoto(file,kind){if(!file)return;if(!file.type.startsWith('image/')||file.size>15*1024*1024){foodMessage('Vyber fotografii JPG/PNG do 15 MB.');return;}const object=URL.createObjectURL(file);let worker;try{foodMessage(kind==='barcode'?'Čtu čárový kód…':'Načítám čtečku etikety…');if(kind==='barcode'){
    let code='';if('BarcodeDetector'in window){try{const detector=new BarcodeDetector({formats:['ean_13','ean_8','upc_a','upc_e']}),bitmap=await createImageBitmap(file);try{const codes=await detector.detect(bitmap);code=codes[0]?.rawValue||'';}finally{bitmap.close();}}catch{}}
    if(!code){const ZX=await loadFoodLibrary('https://cdn.jsdelivr.net/npm/@zxing/browser@0.1.5/umd/zxing-browser.min.js','ZXingBrowser'),reader=new ZX.BrowserMultiFormatReader();const result=await reader.decodeFromImageUrl(object);code=result.getText();}
    if(!/^\d{8,14}$/.test(code))throw new Error('Čárový kód není čitelný. Vyfoť ho rovně a zblízka, nebo opiš číslo.');$('foodBarcode').value=code;$('foodQuery').value='';await searchFood();
  }else{const OCR=await loadFoodLibrary('https://cdn.jsdelivr.net/npm/tesseract.js@5.1.1/dist/tesseract.min.js','Tesseract');worker=await OCR.createWorker('ces+eng',1,{logger:m=>{if(m.status==='recognizing text')foodMessage('Čtu etiketu: '+Math.round(m.progress*100)+' %');}});const result=await worker.recognize(object);$('foodOcrText').value=result.data.text;$('foodOcrDetails').open=true;await applyFoodLabel();}
  }catch(e){foodMessage(kind==='barcode'?'Kód se nepodařilo přečíst. Opiš číslo pod čárovým kódem nebo zkus ostřejší fotografii.':e.message);}finally{if(worker)await worker.terminate();URL.revokeObjectURL(object);}}
