async function loadEnteredFood(){try{const date=$('foodDate').value||pragueToday(),r=await jsonFetch('/app/api/food/day?date='+date);$('enteredFood').innerHTML='<div class="detail-heading"><h3>Zapsaná jídla · '+esc(longDate(date))+'</h3><span class="pill">'+fmt(r.totals?.kcal)+' kcal</span></div>'+(r.entries?.length?r.entries.map(x=>'<div class="foodrow"><div><strong>'+esc(x.recipe_title||'Jídlo')+'</strong><div class="small">'+esc(x.source||'')+' · P '+fmt(x.protein_g,1)+' · S '+fmt(x.carbs_g,1)+' · T '+fmt(x.fat_g,1)+' g</div></div><strong>'+fmt(x.kcal)+' kcal</strong></div>').join(''):'<div class="muted">Zatím žádné jídlo.</div>');}catch(e){$('enteredFood').textContent=e.message;}}
function installFoodEntry(){
  const style=document.createElement('style');style.textContent='.food-controls{display:flex;gap:10px;flex-wrap:wrap;margin:14px 0}.food-controls input{flex:1;min-width:150px}.food-input{background:#0d1119;color:#f6f7fb;border:1px solid #393245;border-radius:9px;padding:10px;max-width:100%;font:inherit}.food-actions{display:flex;gap:8px;flex-wrap:wrap}.food-result{display:block;text-align:left;width:100%;background:#181e29;color:#f6f7fb;border:1px solid #343b4b;border-radius:10px;padding:12px;margin:7px 0}.food-result strong,.food-result span{display:block}.food-editor-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:14px 0}.food-editor-grid label{display:grid;gap:5px;color:#aab3c2;font-size:12px}.food-editor-grid input,.food-editor-grid select{width:100%;min-width:0}.food-upload{display:inline-block;cursor:pointer}.food-ocr-text{width:100%;min-height:130px;resize:vertical}.food-result:hover{border-color:#a978ff}@media(max-width:700px){.food-editor-grid{grid-template-columns:1fr 1fr}.food-actions .btn{flex:1}.food-controls{flex-direction:column}}';document.head.appendChild(style);
  $('nutrition').insertAdjacentHTML('afterbegin','<div class="card" style="margin-bottom:16px" id="foodEntry"><div class="eyebrow">Potraviny a výrobky</div><h3 style="font-size:22px;margin-top:5px">Co jsi snědl?</h3><p class="small">Vyhledej běžnou potravinu, přesný výrobek a značku nebo načti jeho obal.</p><div class="food-controls"><input class="food-input" id="foodQuery" placeholder="Např. jogurt Hollandia, rohlík, banán" aria-label="Název potraviny"><input class="food-input" id="foodBarcode" inputmode="numeric" placeholder="Čárový kód / EAN" aria-label="Čárový kód"><button type="button" class="btn primary" id="foodSearchButton">Dohledat</button></div><div class="food-actions"><label class="btn food-upload">Fotka čárového kódu<input hidden id="foodBarcodePhoto" type="file" accept="image/*" capture="environment"></label><label class="btn food-upload">Fotka nutriční etikety<input hidden id="foodLabelPhoto" type="file" accept="image/*" capture="environment"></label><button type="button" class="btn" id="foodManual">Zadat hodnoty ručně</button></div><div class="small" id="foodEntryStatus" role="status" style="margin-top:12px">Databáze: Open Food Facts · česká nabídka. Fotografie se čtou v prohlížeči.</div><div id="foodResults"></div><details id="foodOcrDetails" style="margin-top:12px"><summary>Text z etikety / vložit zkopírovaný text</summary><textarea id="foodOcrText" class="food-input food-ocr-text" placeholder="Energie 81 kcal&#10;Tuky 1,6 g&#10;Sacharidy 6,4 g&#10;Bílkoviny 10 g"></textarea><button type="button" class="btn" id="foodApplyLabel">Načíst hodnoty z textu</button></details><form id="foodEditor" hidden style="margin-top:16px"><h3>Zkontroluj výrobek a porci</h3><div class="small" id="foodSource"></div><div class="food-editor-grid"><label>Název<input class="food-input" id="foodProductName" required></label><label>Značka<input class="food-input" id="foodBrand"></label><label>Množství · g<input class="food-input" id="foodGrams" inputmode="decimal" value="100" required></label><label>Datum<input type="date" class="food-input" id="foodDate" required></label><label>Jídlo<select class="food-input" id="foodMeal"><option value="breakfast">Snídaně</option><option value="lunch">Oběd</option><option value="dinner">Večeře</option><option value="snack" selected>Svačina</option></select></label></div><div class="label">Hodnoty na 100 g · u tekutin na 100 ml, množství pak zadej v ml</div><div class="food-editor-grid">'+[['calories_100g','Energie · kcal'],['protein_100g','Bílkoviny · g'],['carbs_100g','Sacharidy · g'],['fat_100g','Tuky · g'],['fiber_100g','Vláknina · g'],['salt_100g','Sůl · g']].map(([k,label])=>'<label>'+label+'<input class="food-input" id="food-'+k+'" inputmode="decimal" '+(['fiber_100g','salt_100g'].includes(k)?'':'required')+'></label>').join('')+'</div><div class="notice" id="foodPortionPreview"></div><label class="small" style="display:block;margin:12px 0"><input type="checkbox" id="foodConfirmed" required> Ověřil jsem výrobek, množství a hodnoty na 100 g / ml.</label><button type="submit" class="btn primary" id="foodSaveButton">Zapsat snědené jídlo</button></form><p class="small" style="margin:15px 0 0">Data <a href="https://world.openfoodfacts.org/" target="_blank" rel="noopener noreferrer">Open Food Facts</a> · ODbL. Úplnost českých výrobků se liší; etiketa má přednost.</p></div><div class="card" id="enteredFood" style="margin-bottom:16px"></div>');
  $('foodDate').value=pragueToday();$('foodDate').onchange=loadEnteredFood;$('foodSearchButton').onclick=searchFood;for(const id of ['foodQuery','foodBarcode'])$(id).onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();searchFood();}};
  $('foodBarcodePhoto').onchange=e=>readFoodPhoto(e.target.files[0],'barcode');$('foodLabelPhoto').onchange=e=>readFoodPhoto(e.target.files[0],'label');$('foodApplyLabel').onclick=applyFoodLabel;$('foodManual').onclick=()=>selectFoodProduct({name:$('foodQuery').value.trim(),barcode:$('foodBarcode').value.trim(),source:'package_label'});$('foodEditor').onsubmit=saveFoodEntry;$('foodEditor').oninput=()=>{updateFoodPreview();};loadEnteredFood();
}
installDetailViews();installFoodEntry();$('recovery').insertAdjacentHTML('afterbegin','<div id="whoopSignals" class="card" hidden style="margin-bottom:12px"></div>');
if(location.hash==='#settings')activate('settings');
loadConnections();load().then(async()=>{try{const data=await jsonFetch('/app/api/connections');if(data.providers.find(p=>p.id==='whoop')?.connected)await loadWhoop();}catch{}});
